def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v_no_build = v[:v.index('+')]
        else:
            v_no_build = v

        # Split pre-release
        if '-' in v_no_build:
            version_part, prerelease_part = v_no_build.split('-', 1)
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse major.minor.patch
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        v, original_index = item
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # For comparison: no pre-release sorts after pre-release
        # So we use (major, minor, patch, has_prerelease, prerelease_identifiers, original_index)
        # where has_prerelease is 0 if present (sorts first), 1 if absent (sorts last)
        if prerelease_identifiers is None:
            return (major, minor, patch, 1, [], original_index)
        else:
            return (major, minor, patch, 0, prerelease_identifiers, original_index)

    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for v, _ in sorted_versions]

